content.content:
"""Build a HyperFrames composition from a post storyboard.

Usage:
    python build.py <project_dir>

Reads <project_dir>/storyboard.json and writes <project_dir>/index.html.
The storyboard schema and the scene kinds are documented in ../SKILL.md.

Inline marks inside any text field:
    [[text]]   accent color
    ~~text~~   struck through by an animated line (code lines, list items)
    ((text))   circled by an animated hand-drawn ring
"""

import html
import json
import re
import sys
from pathlib import Path

FONTS = (
    "https://fonts.googleapis.com/css2?family=Anton&family=Inter+Tight:wght@500;700;800"
    "&family=JetBrains+Mono:wght@500;700&family=Instrument+Serif:ital@0;1&display=block"
)


HOOK_MAX = 3.5  # seconds. Scene 2 then builds between 3.1 s and 5 s.
SCENE2_TEMPO = 0.6  # scene 2's entrance offsets are scaled by this


def marks(text: str, sid: str, counter: list) -> str:
    """Escape text, then turn the three inline marks into spans."""
    out = html.escape(text)

    def strike(m):
        counter[0] += 1
        return f'<span class="st" id="{sid}-st{counter[0]}">{m.group(1)}<i></i></span>'

    def ring(m):
        counter[0] += 1
        return (
            f'<span class="ring" id="{sid}-rg{counter[0]}">{m.group(1)}'
            '<svg viewBox="0 0 200 80" preserveAspectRatio="none"><path pathLength="1" '
            'd="M12,44 C10,12 120,4 182,20 C204,30 196,66 120,74 C56,80 4,66 16,34"/></svg></span>'
        )

    out = re.sub(r"~~(.+?)~~", strike, out)
    out = re.sub(r"\(\((.+?)\)\)", ring, out)
    out = re.sub(r"\[\[(.+?)\]\]", r'<span class="ac">\1</span>', out)
    return out


def visual(v: dict, sid: str, c: list) -> str:
    kind = v["kind"]
    if kind == "cover":
        return f'<div class="v v-cover"><div class="covw"><img class="cov" src="{v["src"]}" alt=""><b class="sheen"></b></div></div>'
    if kind == "image":
        return f'<div class="v v-image"><img class="img" src="{v["src"]}" alt=""></div>'
    if kind == "code":
        rows = "".join(
            f'<div class="ln{" dim" if l.startswith("//") else ""}">{marks(l, sid, c) or "&nbsp;"}</div>'
            for l in v["lines"]
        )
        prompt = f'<div class="ln cmd"><b>$</b> <span class="type">{html.escape(v["command"])}</span></div>' if v.get("command") else ""
        return (
            f'<div class="v v-code"><div class="win"><div class="bar"><u></u><u></u><u></u>'
            f'<span>{html.escape(v.get("title", ""))}</span></div><div class="body">{prompt}{rows}</div></div></div>'
        )
    if kind == "fix":
        return (
            '<div class="v v-fix">'
            f'<div class="row bad"><em>✕</em><span>{marks(v["bad"], sid, c)}</span></div>'
            f'<div class="row good"><em>✓</em><span>{marks(v["good"], sid, c)}</span></div></div>'
        )
    if kind == "stats":
        items = "".join(
            f'<div class="stat"><div class="num">{marks(s["num"], sid, c)}</div><div class="lab">{marks(s["label"], sid, c)}</div></div>'
            for s in v["items"]
        )
        img = f'<img class="img" src="{v["src"]}" alt="">' if v.get("src") else ""
        return f'<div class="v v-stats"><div class="stats">{items}</div>{img}</div>'
    if kind == "list":
        items = "".join(f'<div class="li"><b>{i + 1}</b><span>{marks(t, sid, c)}</span></div>' for i, t in enumerate(v["items"]))
        return f'<div class="v v-list">{items}</div>'
    if kind == "swap":
        return (
            '<div class="v v-swap">'
            f'<div class="was">{marks(v["from"], sid, c)}</div><div class="arrow">↓</div>'
            f'<div class="now">{marks(v["to"], sid, c)}</div></div>'
        )
    if kind == "big":
        return f'<div class="v v-big"><div class="bigt">{marks(v["text"], sid, c)}</div></div>'
    raise SystemExit(f"unknown visual kind: {kind}")


def kind_of(s: dict):
    return (s.get("visual") or {}).get("kind")


def css(p: dict, w: int, h: int) -> str:
    return f"""
*{{box-sizing:border-box;margin:0;padding:0}}
html,body{{width:{w}px;height:{h}px;overflow:hidden;background:{p['bg']}}}
#root{{position:relative;width:{w}px;height:{h}px;overflow:hidden;background:{p['bg']};color:{p['ink']};font-family:'Inter Tight',sans-serif}}
#bgfx{{position:absolute;inset:0}}
.glow{{position:absolute;inset:0;background:radial-gradient(ellipse 70% 45% at 85% 0%,{p['accent']}2e,transparent 70%),radial-gradient(ellipse 60% 40% at 0% 100%,{p['accent']}14,transparent 70%)}}
.grain{{position:absolute;inset:0;opacity:.07;mix-blend-mode:overlay;background:url("data:image/svg+xml,%3Csvg viewBox='0 0 300 300' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E")}}
.chrome{{position:absolute;left:72px;right:72px;top:56px;display:flex;justify-content:space-between;align-items:center;padding-bottom:22px;border-bottom:2px solid {p['ink']}26;font:700 26px 'Inter Tight';letter-spacing:5px;text-transform:uppercase;z-index:20}}
.chrome .brand{{display:flex;align-items:center;gap:16px}}
.chrome img{{width:52px;height:52px;border-radius:50%;border:2px solid {p['accent']}}}
.chrome .kick{{color:{p['muted']}}}
.prog{{position:absolute;left:0;bottom:0;height:10px;width:100%;background:{p['accent']};transform-origin:0 50%;z-index:20}}
.scene{{position:absolute;inset:0;z-index:5}}
.sc{{position:absolute;inset:0;padding:170px 72px 86px;display:flex;flex-direction:column;gap:34px}}
.label{{font:700 28px 'JetBrains Mono',monospace;letter-spacing:4px;text-transform:uppercase;color:{p['accent']}}}
.hl{{font-family:'Instrument Serif',serif;font-size:92px;line-height:1.0;letter-spacing:-1px;max-width:930px}}
.hl.xl{{font-size:116px}}
.sc.center{{justify-content:center;padding-bottom:200px}}
.cap{{font:700 40px/1.25 'Inter Tight',sans-serif;color:{p['ink']};max-width:920px}}
.cap.q{{font-family:'Instrument Serif',serif;font-weight:400;font-size:56px;line-height:1.1}}
.cta{{align-self:flex-start;font:800 36px 'Inter Tight';color:{p['bg']};background:{p['accent']};padding:18px 28px;border-radius:12px}}
.ac{{color:{p['accent']}}}
.v{{flex:1;min-height:0;display:flex;flex-direction:column;justify-content:center}}
.v-cover{{align-items:center}}
.covw{{position:relative;height:100%;max-height:640px;border-radius:18px;overflow:hidden;box-shadow:0 40px 90px #000a,0 0 0 2px {p['ink']}1f}}
.cov{{display:block;height:100%}}
.sheen{{position:absolute;top:-20%;bottom:-20%;left:0;width:34%;transform:translateX(-160%) rotate(12deg);background:linear-gradient(90deg,transparent,#ffffff38,transparent)}}
#s0 .hl .ac{{background:linear-gradient({p['accent']}55,{p['accent']}55) no-repeat 0 92%;background-size:0% 24%}}
.v-image{{align-items:center}}
.img{{max-width:100%;max-height:420px;border-radius:14px;box-shadow:0 24px 60px #0009}}
.win{{background:{p['panel']};border-radius:18px;border:2px solid {p['ink']}1f;box-shadow:0 30px 70px #0009;overflow:hidden}}
.bar{{display:flex;gap:12px;align-items:center;padding:20px 26px;border-bottom:2px solid {p['ink']}14;font:500 24px 'JetBrains Mono';color:{p['muted']}}}
.bar u{{width:18px;height:18px;border-radius:50%;background:#ff5f57}}.bar u:nth-child(2){{background:#febc2e}}.bar u:nth-child(3){{background:#28c840;margin-right:14px}}
.body{{padding:26px 30px 32px;display:flex;flex-direction:column;gap:16px;font:500 40px/1.3 'JetBrains Mono',monospace;white-space:pre-wrap}}
.ln.dim{{color:{p['muted']}}}
.ln.cmd b{{color:{p['accent']}}}
.type{{display:inline-block;white-space:nowrap;overflow:hidden;vertical-align:bottom}}
.st{{position:relative;display:inline}}
.st i{{position:absolute;left:-4px;right:-4px;top:52%;height:4px;background:{p['bad']};transform-origin:0 50%;border-radius:3px}}
.ring{{position:relative;display:inline-block}}
.ring svg{{position:absolute;left:-22px;top:-20px;width:calc(100% + 44px);height:calc(100% + 40px);overflow:visible}}
.ring path{{fill:none;stroke:{p['bad']};stroke-width:5;stroke-linecap:round;stroke-dasharray:1;stroke-dashoffset:1}}
.v-fix{{gap:24px}}
.row{{display:flex;gap:26px;align-items:flex-start;padding:30px 32px;border-radius:18px;font:700 46px/1.22 'Inter Tight'}}
.row em{{font-style:normal;flex:none;width:58px;height:58px;border-radius:50%;display:grid;place-items:center;font-size:32px}}
.row.bad{{background:{p['bad']}1f;border:2px solid {p['bad']}66;color:{p['muted']}}}.row.bad em{{background:{p['bad']};color:#fff}}
.row.good{{background:{p['panel']};border:2px solid {p['ink']}33}}.row.good em{{background:{p['ink']};color:{p['bg']}}}
.v-stats{{gap:40px}}
.stats{{display:flex;gap:56px}}
.num{{font:400 168px/0.9 'Anton',sans-serif;color:{p['accent']};letter-spacing:-1px}}
.lab{{font:700 34px 'Inter Tight';color:{p['ink']};margin-top:10px}}
.v-list{{gap:34px}}
.li{{display:flex;gap:26px;align-items:flex-start;font:700 50px/1.2 'Inter Tight'}}
.li b{{flex:none;font:400 62px/1 'Anton';color:{p['accent']};width:48px}}
.v-swap{{gap:18px;font-family:'Instrument Serif',serif}}
.was{{font-size:64px;color:{p['muted']}}}
.arrow{{font:700 54px 'Inter Tight';color:{p['accent']}}}
.now{{font-size:76px;line-height:1.05}}
.v-big{{justify-content:center}}
.bigt{{font:400 120px/1.05 'Anton',sans-serif;text-transform:uppercase;overflow-wrap:anywhere}}
"""


def build(project: Path) -> None:
    sb = json.loads((project / "storyboard.json").read_text(encoding="utf-8"))
    w, h, p = sb.get("width", 1080), sb.get("height", 1350), sb["palette"]
    xfade = 0.4

    scenes_html, js, t = [], [], 0.0
    hook = sb["scenes"][0]
    if hook["dur"] > HOOK_MAX:
        print(f"note: scene 1 runs {hook['dur']}s, capped at {HOOK_MAX}s so scene 2 lands inside the first 5 s")
        hook["dur"] = HOOK_MAX
    for i, s in enumerate(sb["scenes"]):
        sid, c = f"s{i}", [0]
        dur = s["dur"]
        start = max(0.0, t - (xfade if i else 0))
        length = dur + (xfade if i else 0)
        parts = []
        if s.get("label"):
            parts.append(f'<div class="label">{marks(s["label"], sid, c)}</div>')
        if s.get("headline"):
            parts.append(f'<div class="hl{" xl" if s.get("xl") else ""}">{marks(s["headline"], sid, c)}</div>')
        if s.get("visual"):
            parts.append(visual(s["visual"], sid, c))
        if s.get("caption"):
            parts.append(f'<div class="cap{" q" if s.get("quote") else ""}">{marks(s["caption"], sid, c)}</div>')
        if s.get("cta"):
            parts.append(f'<div class="cta">{marks(s["cta"], sid, c)}</div>')
        scenes_html.append(
            f'<div id="{sid}" class="scene clip" data-start="{start:.2f}" data-duration="{length:.2f}" '
            f'data-track-index="{i + 2}"><div class="sc{" center" if not s.get("visual") else ""}">{"".join(parts)}</div></div>'
        )

        # Transition in: crossfade with a small rise. The transition is the only exit.
        if i:
            js.append(f"tl.fromTo('#{sid}',{{autoAlpha:0,y:24}},{{autoAlpha:1,y:0,duration:{xfade},ease:'power2.inOut'}},{start:.2f});")
            js.append(f"tl.to('#s{i - 1}',{{autoAlpha:0,duration:.25,ease:'power1.in'}},{start:.2f});")
        # Entrances start with the crossfade, so the incoming scene never shows empty.
        b = start + 0.2  # the outgoing scene is gone by +0.25s, so two headlines never overlap
        if i == 0:
            # Frame 0 is the feed thumbnail, so scene 1 is drawn complete at frame 0.
            # It must also move from frame 0: a still first second reads as an image
            # in the feed and the viewer scrolls past (Atharva, 2026-10-09).
            k0 = kind_of(s)
            if k0 == "cover":
                js.append(f"tl.fromTo('#{sid} .covw',{{scale:1,y:0,rotation:-1.5}},{{scale:1.07,y:-16,rotation:1.5,duration:{dur:.2f},ease:'sine.inOut'}},0);")
                js.append(f"tl.fromTo('#{sid} .sheen',{{xPercent:-160,rotation:12}},{{xPercent:420,duration:1.1,ease:'power2.inOut'}},0.25);")
                js.append(f"tl.fromTo('#{sid} .sheen',{{xPercent:-160}},{{xPercent:420,duration:1.1,ease:'power2.inOut',immediateRender:false}},1.9);")
            elif k0 == "image":
                js.append(f"tl.fromTo('#{sid} .v img',{{scale:1,y:0}},{{scale:1.08,y:-14,duration:{dur:.2f},ease:'sine.inOut'}},0);")
            elif k0 == "big":
                js.append(f"tl.fromTo('#{sid} .bigt',{{scale:1,transformOrigin:'0% 50%'}},{{scale:1.08,duration:{dur:.2f},ease:'sine.inOut'}},0);")
            elif k0:
                js.append(f"tl.fromTo('#{sid} .v',{{scale:1,y:0}},{{scale:1.05,y:-12,duration:{dur:.2f},ease:'sine.inOut'}},0);")
            js.append(f"tl.to('#{sid} .hl .ac',{{backgroundSize:'100% 24%',duration:.7,stagger:.3,ease:'power2.out'}},0.35);")
            if s.get("caption"):
                js.append(f"tl.from('#{sid} .cap',{{autoAlpha:0,y:30,duration:.55,ease:'power3.out'}},1.0);")
            t += dur
            continue
        first = len(js)
        if s.get("label"): js.append(f"tl.from('#{sid} .label',{{autoAlpha:0,x:-30,duration:.45,ease:'power3.out'}},{b:.2f});")
        if s.get("headline"): js.append(f"tl.from('#{sid} .hl',{{autoAlpha:0,y:40,duration:.7,ease:'expo.out'}},{b + .12:.2f});")
        vb = b + 0.55
        kind = (s.get("visual") or {}).get("kind")
        if kind in ("cover", "image"):
            # A cover animates its frame, so the frame never shows empty before the card.
            tgt = ".covw" if kind == "cover" else ".v img"
            js.append(f"tl.from('#{sid} {tgt}',{{autoAlpha:0,y:60,scale:.94,duration:.9,ease:'power3.out'}},{vb:.2f});")
            js.append(f"tl.to('#{sid} {tgt}',{{scale:1.03,duration:{max(dur - 1.5, 1):.2f},ease:'none'}},{vb + .9:.2f});")
        elif kind == "code":
            js.append(f"tl.from('#{sid} .win',{{autoAlpha:0,y:50,duration:.6,ease:'power3.out'}},{vb:.2f});")
            if s["visual"].get("command"):
                js.append(f"tl.from('#{sid} .type',{{width:0,duration:.9,ease:'steps({len(s['visual']['command'])})'}},{vb + .4:.2f});")
                vb += 0.9
            js.append(f"tl.from('#{sid} .body .ln:not(.cmd)',{{autoAlpha:0,x:-24,duration:.35,stagger:.12,ease:'power2.out'}},{vb + .45:.2f});")
        elif kind == "fix":
            js.append(f"tl.from('#{sid} .row.bad',{{autoAlpha:0,x:-50,duration:.55,ease:'power3.out'}},{vb:.2f});")
            js.append(f"tl.from('#{sid} .row.good',{{autoAlpha:0,y:40,duration:.6,ease:'back.out(1.6)'}},{vb + 1.3:.2f});")
        elif kind == "stats":
            js.append(f"tl.from('#{sid} .stat',{{autoAlpha:0,y:50,scale:.9,duration:.6,stagger:.35,ease:'back.out(1.7)'}},{vb:.2f});")
            if s["visual"].get("src"): js.append(f"tl.from('#{sid} .v-stats .img',{{autoAlpha:0,y:40,duration:.6,ease:'power3.out'}},{vb + .7:.2f});")
        elif kind == "list":
            js.append(f"tl.from('#{sid} .li',{{autoAlpha:0,x:-40,duration:.5,stagger:.6,ease:'power3.out'}},{vb:.2f});")
        elif kind == "swap":
            js.append(f"tl.from('#{sid} .was',{{autoAlpha:0,y:30,duration:.5,ease:'power2.out'}},{vb:.2f});")
            js.append(f"tl.from('#{sid} .arrow',{{autoAlpha:0,y:-20,duration:.4,ease:'power2.out'}},{vb + 1.4:.2f});")
            js.append(f"tl.from('#{sid} .now',{{autoAlpha:0,y:40,duration:.6,ease:'back.out(1.5)'}},{vb + 1.6:.2f});")
        elif kind == "big":
            js.append(f"tl.from('#{sid} .bigt',{{autoAlpha:0,scale:.85,duration:.7,ease:'expo.out'}},{vb:.2f});")
        if s.get("caption"): js.append(f"tl.from('#{sid} .cap',{{autoAlpha:0,y:24,duration:.5,ease:'power2.out'}},{b + 1.5:.2f});")
        if s.get("cta"): js.append(f"tl.from('#{sid} .cta',{{autoAlpha:0,scale:.9,duration:.5,ease:'back.out(2)'}},{b + 2.4:.2f});")
        # Marks fire after their line has landed: strikes at +1.6s, rings at +2.2s, in source order.
        body = "".join(parts)
        for n, mid in enumerate(re.findall(rf'id="({sid}-st\d+)"', body)):
            js.append(f"tl.from('#{mid} i',{{scaleX:0,duration:.35,ease:'power2.inOut'}},{b + s.get('mark_at', 1.7) + n * .25:.2f});")
        for mid in re.findall(rf'id="({sid}-rg\d+)"', body):
            js.append(f"tl.to('#{mid} path',{{strokeDashoffset:0,duration:.6,ease:'power2.out'}},{b + s.get('mark_at', 1.7) + .5:.2f});")
        if i == 1:
            # Scene 2 builds at 0.6x tempo, so the first 5 seconds never hold still
            # while its visual waits to land. Measured by run.py's motion gate.
            def faster(m, b=b):
                pos = float(m.group(1))
                return f",{b + (pos - b) * SCENE2_TEMPO:.2f});" if pos > b else m.group(0)
            js[first:] = [re.sub(r",(\d+\.\d+)\);$", faster, line) for line in js[first:]]
        t += dur

    total = round(t, 2)
    chrome = (
        f'<div id="chrome" class="chrome clip" data-start="0" data-duration="{total}" data-track-index="1">'
        f'<div class="brand"><img src="{sb["avatar"]}" alt="">{html.escape(sb["brand"])}</div>'
        f'<div class="kick">{html.escape(sb["kicker"])}</div></div>'
    )
    js.insert(0, f"tl.fromTo('#prog',{{scaleX:0}},{{scaleX:1,duration:{total},ease:'none'}},0);")

    doc = f"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><title>{html.escape(sb['title'])}</title>
<link rel="stylesheet" href="{FONTS}">
<script src="assets/gsap.min.js"></script>
<style>{css(p, w, h)}</style></head><body>
<div id="root" data-composition-id="{sb['id']}" data-start="0" data-duration="{total}" data-width="{w}" data-height="{h}">
<div id="bgfx" class="clip" data-start="0" data-duration="{total}" data-track-index="0"><div class="glow"></div><div class="grain"></div></div>
{chrome}
{chr(10).join(scenes_html)}
<div id="prog" class="prog clip" data-start="0" data-duration="{total}" data-track-index="{len(sb['scenes']) + 2}"></div>
</div>
<script>
const tl=gsap.timeline({{paused:true}});
{chr(10).join(js)}
window.__timelines=window.__timelines||{{}};window.__timelines['{sb['id']}']=tl;
</script></body></html>
"""
    (project / "index.html").write_text(doc, encoding="utf-8")
    print(f"{project.name}: {len(sb['scenes'])} scenes, {total}s, {w}x{h}")


if __name__ == "__main__":
    build(Path(sys.argv[1]))

# Source this in Git Bash before any video-make or video-edit command:
#   source ~/.claude/skills/video-make/scripts/studio-env.sh
#
# It sets up one shell for the studio. Each step fixed a real failure:
#   1. VIDEO_STUDIO: D:/Atharva/video-studio when D:/Atharva exists, else
#      ~/video-studio, so a new PC without a D: drive still works.
#   2. Node 22 first on PATH. The kit and HyperFrames refuse Node 20. fnm holds
#      Node 22 next to whatever system Node exists.
#   3. ffmpeg 6 or newer first on PATH. ImageMagick ships ffmpeg 4.2.3 and can
#      sit ahead of a modern build.
#   4. A real Python 3.10+ on PATH, never the Microsoft Store alias stub.
# Tools are also found in their standard install folders, because PATH does not
# refresh inside a shell that was open when winget installed them.
# The Bash tool keeps no env between calls, so source this in every call.

if [ -z "${VIDEO_STUDIO:-}" ]; then
  if [ -d /d/Atharva ]; then export VIDEO_STUDIO=/d/Atharva/video-studio
  else export VIDEO_STUDIO="$HOME/video-studio"; fi
fi
export VIDEO_SKILLS="${VIDEO_SKILLS:-$HOME/.claude/skills}"
_lad="$(cygpath -u "${LOCALAPPDATA:-$HOME/AppData/Local}" 2>/dev/null || echo "$HOME/AppData/Local")"
_apd="$(cygpath -u "${APPDATA:-$HOME/AppData/Roaming}" 2>/dev/null || echo "$HOME/AppData/Roaming")"
_wgl="$_lad/Microsoft/WinGet/Links"
case ":$PATH:" in *":$_wgl:"*) ;; *) [ -d "$_wgl" ] && export PATH="$PATH:$_wgl" ;; esac

_studio_node22() {
  local d="" c
  if command -v fnm >/dev/null 2>&1; then
    d="$(fnm exec --using=22 -- node -p "require('path').dirname(process.execPath)" 2>/dev/null | tr -d '\r')"
    [ -n "$d" ] && d="$(cygpath -u "$d" 2>/dev/null || echo "$d")"
  fi
  if [ -z "$d" ]; then
    for c in "$_apd"/fnm/node-versions/v22.*/installation "$_lad"/fnm_multishells/*/; do
      [ -x "$c/node.exe" ] && "$c/node.exe" -v 2>/dev/null | grep -q '^v2[2-9]' && d="$c"
    done
  fi
  [ -z "$d" ] && command -v node >/dev/null 2>&1 && node -v | grep -q '^v2[2-9]' && d="$(dirname "$(command -v node)")"
  [ -n "$d" ] && echo "$d"
}

_studio_ffmpeg_dir() {
  local f v IFS=$'\n'   # split on newlines only: paths can hold spaces
  for f in /c/ProgramData/chocolatey/bin/ffmpeg "$_wgl/ffmpeg" \
           $(ls -d "$_lad"/Microsoft/WinGet/Packages/Gyan.FFmpeg*/ffmpeg-*/bin/ffmpeg.exe 2>/dev/null) \
           $(which -a ffmpeg 2>/dev/null); do
    [ -x "$f" ] || [ -x "$f.exe" ] || continue
    v="$("$f" -version 2>/dev/null | head -1 | sed -E 's/^ffmpeg version n?([0-9]+).*/\1/')"
    case "$v" in ''|*[!0-9]*) continue ;; esac
    if [ "$v" -ge 6 ]; then dirname "$f"; return; fi
  done
}

_studio_python_dir() {
  local p IFS=$'\n'   # split on newlines only: "Program Files" holds a space
  for p in $(which -a python 2>/dev/null) $(ls -d "$_lad"/Programs/Python/Python3*/python.exe /c/Program\ Files/Python3*/python.exe 2>/dev/null); do
    case "$p" in */WindowsApps/*) continue ;; esac
    [ -x "$p" ] || [ -x "$p.exe" ] || continue
    "$p" -c "import sys; sys.exit(0 if sys.version_info >= (3, 10) else 1)" 2>/dev/null && { dirname "$p"; return; }
  done
}

_n22="$(_studio_node22)"
_ffd="$(_studio_ffmpeg_dir)"
_pyd="$(_studio_python_dir)"
[ -n "$_n22" ] && export PATH="$_n22:$PATH"
[ -n "$_ffd" ] && export PATH="$_ffd:$PATH" && export FFMPEG_DIR="$(cygpath -w "$_ffd" 2>/dev/null || echo "$_ffd")"
[ -n "$_pyd" ] && export PATH="$_pyd:$_pyd/Scripts:$PATH"
export PYTHONIOENCODING=utf-8

[ -z "$_n22" ] && echo "studio-env: Node 22 not found. Run setup.sh" >&2
[ -z "$_ffd" ] && echo "studio-env: no ffmpeg >= 6 found. Run setup.sh" >&2
[ -z "$_pyd" ] && echo "studio-env: no Python 3.10+ found. Run setup.sh" >&2
unset _n22 _ffd _pyd _lad _apd _wgl
