"""Build the FirstRun teaser composition for one format.

Usage: python build_teaser.py 4x5|9x16|16x9

Writes index.html and meta.json in this folder. Every fact on screen is listed
with its source in VERIFY.md. Look follows firstrun-concept/DESIGN.md with the
site palette: light page, Geist, accent #0A66D6, pass #1B8A3A, fail #C4281C.
"""
import json
import sys
from pathlib import Path

HERE = Path(__file__).parent

FMT = {
    "4x5": dict(w=1080, h=1350, land=False, pad="176px 72px 96px", hl=74, cap=38, lab=24, vw=936, gap=34, mono=36),
    "9x16": dict(w=1080, h=1920, land=False, pad="250px 72px 300px", hl=84, cap=42, lab=26, vw=936, gap=48, mono=36),
    "16x9": dict(w=1920, h=1080, land=True, pad="150px 110px 90px", hl=70, cap=34, lab=22, vw=980, gap=26, mono=36),
}

# Scene durations in seconds. The hook is short so scene 2 builds inside the first 5 s.
DUR = [4.5, 5.5, 5.5, 6.5, 6.0, 4.5, 4.0]
XF = 0.4

CHECK = '<svg class="ic" viewBox="0 0 34 34"><circle cx="17" cy="17" r="17"/><path d="M10 17.5l4.6 4.6L24 12.5"/></svg>'
CROSS = '<svg class="ic bad" viewBox="0 0 34 34"><circle cx="17" cy="17" r="17"/><path d="M11.5 11.5l11 11M22.5 11.5l-11 11"/></svg>'


def step_card(cid: str, green_layer: bool) -> str:
    """The step 10 card. With green_layer it also holds the passed state, hidden at start."""
    g = ""
    if green_layer:
        g = (
            f'<span class="icw g">{CHECK}</span>'
        )
    return f"""
<div class="card step" id="{cid}">
  <div class="sh">
    <span class="icwrap"><span class="icw r">{CROSS}</span>{g}</span>
    <div class="stt"><div class="k mono">Step 10 of 10</div><div class="t">Generate 6 years of Jaffle Shop data</div></div>
    <span class="pillwrap"><span class="pill bad">failed, exit 2</span>{'<span class="pill good">passed, exit 0</span>' if green_layer else ''}</span>
  </div>
  <div class="cmdl mono"><b>$</b> <span class="cw"><span class="c1">jafgen --years 6</span>{'<span class="c2">jafgen 6</span>' if green_layer else ''}</span></div>
  <div class="errl mono"><span>No such option: --years</span></div>
  <div class="scan"></div>
</div>"""


def scenes() -> list[dict]:
    return [
        dict(label="dbt DuckDB guide", hl='Step 10 of the dbt guide <span class="r">fails</span>.',
             vis=step_card("stepA", False),
             cap="Copy the command from the docs, and jafgen rejects the flag."),
        dict(label="1 · Diagnose", hl="FirstRun reads the real error.",
             vis='<div class="card plate" id="errplate"><div class="bar mono">Attempt 1 output, from the run</div>'
                 '<div class="pimg"><img src="assets/plates/error.png" alt=""><i class="uline"></i></div></div>'
                 '<div class="chip" id="chip1"><span class="dot r"></span>Classified as a docs bug, confidence 1.0</div>',
             cap="The usage line shows <span class=\"m\">years</span> is now a positional argument."),
        dict(label="2 · Fix", hl="The patch drops one flag.",
             vis='<div class="card diff"><div class="bar mono">patch.diff · the jafgen line in the guide</div>'
                 '<div class="ctx mono">to generate data for 6 years, run</div>'
                 '<div class="dl del mono"><i>-</i><span class="st">jafgen --years 6<u></u></span></div>'
                 '<div class="dl add mono"><i>+</i><span>jafgen 6</span></div></div>',
             cap="FirstRun edits the docs sentence, then drafts the PR body."),
        dict(label="3 · Prove", hl='A fresh container passes <span class="g">9 of 9</span>.',
             vis=step_card("stepB", True) +
                 '<div class="card plate sm" id="provenplate"><div class="pimg"><img src="assets/plates/proven.png" alt=""></div></div>',
             cap="The proof run makes no model calls. The whole run cost $0.03."),
        dict(label="4 · Bisect", hl='jafgen <span class="r">0.4.6</span> removed the flag.',
             vis=timeline(),
             cap="5 probes, one clean container each, $0 in model calls. The guide shipped 11 months later."),
        dict(label="5 · Ship", hl="FirstRun opened 4 upstream docs PRs.",
             vis=pr_fan(),
             cap="dbt-labs #10149 and #10150, entireio/cli #2724, accuknox/help #671."),
        dict(end=True),
    ]


def timeline() -> str:
    rel = [("0.2.1", "Jan 2023", True), ("0.3.1", "Jan 2023", True), ("0.4.6", "Apr 2024", False),
           ("0.4.10", "Apr 2024", False), ("0.4.14", "Apr 2024", False)]
    nodes = "".join(
        f'<div class="nd {"ok" if ok else "no"}{" first" if v == "0.4.6" else ""}" style="left:{i * 15.5}%">'
        f'<div class="v mono">{v}</div><div class="dotn">{CHECK if ok else CROSS}</div><div class="d">{d}</div></div>'
        for i, (v, d, ok) in enumerate(rel)
    )
    return f"""
<div class="card tlc">
  <div class="bar mono">firstrun bisect --package jafgen</div>
  <div class="track">
    <div class="rail"></div><div class="gapline"></div>
    {nodes}
    <div class="nd guide" style="left:92%"><div class="v mono">guide</div><div class="dotn"><span></span></div><div class="d">Mar 2025</div></div>
    <div class="brace"><span>11 months</span></div>
    <div class="fb mono">first bad</div>
  </div>
</div>"""


def pr_fan() -> str:
    prs = ["pr-10149", "pr-10150", "pr-2724", "pr-671"]
    cards = "".join(f'<img class="pr p{i}" src="assets/plates/{p}.webp" alt="">' for i, p in enumerate(prs))
    return f'<div class="fan">{cards}<div class="cnt"><b>4</b><span>upstream docs PRs</span></div></div>'


