.diff .ctx{{padding:26px 30px 6px;font-size:28px;color:var(--muted)}}
.dl{{display:flex;align-items:center;gap:22px;margin:12px 22px;padding:20px 22px;border-radius:14px;font-size:{f['mono'] + 6}px;font-weight:500}}
.dl i{{font-style:normal;width:30px;text-align:center;font-weight:700}}
.dl.del{{background:var(--fail-soft);color:var(--fail)}} .dl.add{{background:var(--pass-soft);color:var(--pass);margin-bottom:30px}}
.dl .st{{position:relative}} .dl .st u{{position:absolute;left:-4px;right:-4px;top:52%;height:4px;background:var(--fail);border-radius:2px;transform-origin:0 50%}}
/* timeline */
.track{{position:relative;height:300px;margin:0 34px}}
.rail{{position:absolute;left:4%;right:30%;top:132px;height:4px;background:var(--line);border-radius:2px}}
.gapline{{position:absolute;left:66%;right:4%;top:132px;height:0;border-top:4px dashed var(--line)}}
.nd{{position:absolute;top:48px;width:110px;margin-left:-14px;display:flex;flex-direction:column;align-items:center}}
.nd .v{{font-size:28px;font-weight:600;height:40px}}
.nd .dotn{{width:56px;height:56px;margin-top:10px;border-radius:50%;background:var(--card)}}
.nd .d{{margin-top:14px;font-size:22px;color:var(--muted);white-space:nowrap}}
.nd.no .v{{color:var(--fail)}} .nd.ok .v{{color:var(--pass)}}
.nd.guide .v{{color:var(--accent)}} .nd.guide .dotn{{display:grid;place-items:center;border:4px solid var(--accent)}} .nd.guide .dotn span{{width:22px;height:22px;border-radius:50%;background:var(--accent)}}
.nd.first .dotn{{box-shadow:0 0 0 8px rgba(196,40,28,.16)}}
.brace{{position:absolute;left:31%;width:62%;top:226px;height:22px;border:3px solid var(--accent);border-top:none;border-radius:0 0 14px 14px;transform-origin:0 0}}
.brace span{{position:absolute;left:50%;top:30px;transform:translateX(-50%);font-weight:700;font-size:32px;color:var(--accent);white-space:nowrap;letter-spacing:-.02em}}
.fb{{position:absolute;left:31%;top:8px;margin-left:-14px;font-size:20px;color:#fff;background:var(--fail);padding:4px 12px;border-radius:999px;transform:translateX(0)}}
.tlc .track{{margin-bottom:24px}}
/* PR fan */
.fan{{position:relative;height:{560 if not f['land'] else 620}px}}
.pr{{position:absolute;width:{int(vw * .64)}px;border-radius:16px;box-shadow:var(--shadow);border:1px solid rgba(29,29,31,.1);background:#fff}}
.cnt{{position:absolute;right:0;bottom:0;display:flex;align-items:baseline;gap:16px;background:var(--card);padding:18px 30px;border-radius:22px;box-shadow:var(--shadow)}}
.cnt b{{font-size:110px;line-height:1;color:var(--accent);letter-spacing:-.04em}} .cnt span{{font-size:32px;font-weight:600;max-width:200px;line-height:1.1}}
/* end card */
.endc{{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:30px;padding-bottom:40px}}
.endc .logo{{width:170px;height:170px}}
.endc .wm{{font-weight:700;font-size:{120 if f['land'] else 116}px;letter-spacing:-.05em;line-height:1}}
.endc .tag{{font-weight:500;font-size:48px;color:var(--muted);letter-spacing:-.02em}}
.endc .tag b{{color:var(--fail);font-weight:600}} .endc .tag i{{color:var(--accent);font-style:normal;font-weight:600}} .endc .tag em{{color:var(--pass);font-style:normal;font-weight:600}}
.endc .url{{margin-top:14px;font:600 44px 'Geist Mono';color:#fff;background:var(--accent);padding:20px 38px;border-radius:999px;letter-spacing:-.01em}}
.endc .built{{margin-top:26px;display:flex;align-items:center;gap:18px;font-size:26px;color:var(--muted);font-weight:500}}
.endc .built img{{width:52px;height:52px;border-radius:12px}}
"""


def build(fmt: str) -> None:
    f = FMT[fmt]
    sc = scenes()
    total = round(sum(DUR), 2)
    html, js, t = [], [], 0.0
    E = "'expo.out'"
    for i, s in enumerate(sc):
        dur = DUR[i]
        start = max(0.0, t - (XF if i else 0))
        length = dur + (XF if i else 0)
        sid = f"s{i}"
        if s.get("end"):
            inner = ('<div class="endc"><img class="logo" src="assets/logo.svg" alt=""><div class="wm">FirstRun</div>'
                     '<div class="tag"><b>Break.</b> <i>Fix.</i> <em>Prove.</em></div>'
                     '<div class="url">firstrun.atharvashah.com</div>'
                     '<div class="built">Built with <img src="assets/logos/entire-apple.png" alt="Entire">'
                     '<img src="assets/logos/neatlogs-apple.png" alt="neatlogs"><img src="assets/logos/cfoai-apple.png" alt="cfo.ai"></div></div>')
        else:
            inner = (f'<div class="sc"><div class="label">{s["label"]}</div><div class="hl">{s["hl"]}</div>'
                     f'<div class="vis">{s["vis"]}</div><div class="cap">{s["cap"]}</div></div>')
        html.append(f'<div id="{sid}" class="scene clip" data-start="{start:.2f}" data-duration="{length:.2f}" data-track-index="{i + 2}">{inner}</div>')
        S = f"#{sid}"
        if i:
            js.append(f"tl.fromTo('{S}',{{autoAlpha:0,y:24,filter:'blur(8px)'}},{{autoAlpha:1,y:0,filter:'blur(0px)',duration:{XF},ease:'power2.out'}},{start:.2f});")
            js.append(f"tl.to('#s{i - 1}',{{autoAlpha:0,duration:.25,ease:'power1.in'}},{start:.2f});")
        b = start + 0.2 if i else 0.0
        if i == 0:
            # Frame 0 is the thumbnail: drawn complete. It moves from frame 0.
            js += [
                f"tl.fromTo('{S} .vis',{{scale:1,y:0,rotation:-1.2}},{{scale:1.06,y:-14,rotation:1.2,duration:{dur},ease:'sine.inOut'}},0);",
                f"tl.fromTo('{S} .scan',{{y:-100}},{{y:420,duration:1.3,ease:'power1.inOut',repeat:2}},0);",
                f"tl.fromTo('{S} .step',{{boxShadow:'0 0 0 0px rgba(196,40,28,.0), 0 30px 70px -24px rgba(29,29,31,.22)'}},{{boxShadow:'0 0 0 22px rgba(196,40,28,.18), 0 30px 70px -24px rgba(29,29,31,.22)',duration:.7,ease:'sine.inOut',yoyo:true,repeat:5}},0);",
                f"tl.fromTo('{S} .errl',{{x:0}},{{keyframes:{{x:[-10,10,-8,8,-4,0]}},duration:.5,ease:'none'}},1.0);",
                f"tl.from('{S} .cap',{{autoAlpha:0,y:30,duration:.55,ease:{E}}},1.0);",
            ]
            t += dur
            continue
        if s.get("end"):
            js += [
                f"tl.from('{S} .logo',{{autoAlpha:0,scale:.6,rotation:-12,duration:.8,ease:'back.out(1.6)'}},{b:.2f});",
                f"tl.from('{S} .wm',{{autoAlpha:0,y:40,duration:.7,ease:{E}}},{b + .25:.2f});",
                f"tl.from('{S} .tag>*',{{autoAlpha:0,y:24,duration:.5,stagger:.22,ease:{E}}},{b + .5:.2f});",
                f"tl.from('{S} .url',{{autoAlpha:0,scale:.85,duration:.6,ease:'back.out(1.8)'}},{b + 1.2:.2f});",
                f"tl.from('{S} .built',{{autoAlpha:0,y:20,duration:.5,ease:{E}}},{b + 1.6:.2f});",
                f"tl.to('{S} .endc',{{scale:1.04,duration:{dur:.2f},ease:'none'}},{b:.2f});",
            ]
            t += dur
            continue
        js += [
            f"tl.from('{S} .label',{{autoAlpha:0,x:-30,duration:.45,ease:{E}}},{b:.2f});",
            f"tl.from('{S} .hl',{{autoAlpha:0,y:40,duration:.7,ease:{E}}},{b + .1:.2f});",
            f"tl.from('{S} .cap',{{autoAlpha:0,y:24,duration:.55,ease:{E}}},{b + 1.3:.2f});",
            f"tl.to('{S} .vis',{{scale:1.025,duration:{dur:.2f},ease:'none'}},{b:.2f});",
        ]
        v = b + 0.35
        if i == 1:
            js += [
                f"tl.from('{S} #errplate',{{autoAlpha:0,y:50,scale:.96,duration:.7,ease:{E}}},{v:.2f});",
                f"tl.from('{S} .uline',{{scaleX:0,duration:.45,ease:'power2.inOut'}},{v + .9:.2f});",
                f"tl.from('{S} #chip1',{{autoAlpha:0,y:20,duration:.5,ease:'back.out(1.6)'}},{v + 1.3:.2f});",
            ]
        elif i == 2:
            js += [
                f"tl.from('{S} .diff',{{autoAlpha:0,y:50,duration:.6,ease:{E}}},{v:.2f});",
                f"tl.from('{S} .dl.del',{{autoAlpha:0,x:-60,duration:.5,ease:{E}}},{v + .35:.2f});",
                f"tl.from('{S} .dl.del .st u',{{scaleX:0,duration:.45,ease:'power2.inOut'}},{v + 1.1:.2f});",
                f"tl.to('{S} .dl.del',{{opacity:.55,duration:.4}},{v + 1.5:.2f});",
                f"tl.from('{S} .dl.add',{{autoAlpha:0,x:60,duration:.6,ease:'back.out(1.4)'}},{v + 1.6:.2f});",
            ]
        elif i == 3:
            # The red step turns green: the hero moment.
            g = v + 0.9
            js += [
                f"tl.from('{S} .step',{{autoAlpha:0,y:40,duration:.5,ease:{E}}},{v:.2f});",
                f"tl.set('{S} .icw.g,{S} .pill.good,{S} .c2',{{autoAlpha:0}},0);",
                f"tl.fromTo('{S} .scan',{{y:-100}},{{y:420,duration:.8,ease:'power1.inOut'}},{v + .1:.2f});",
                f"tl.to('{S} .errl',{{height:0,paddingTop:0,paddingBottom:0,marginTop:0,marginBottom:22,opacity:0,duration:.5,ease:'power2.inOut'}},{g:.2f});",
                f"tl.to('{S} .c1',{{autoAlpha:0,y:-20,duration:.3}},{g:.2f});",
                f"tl.fromTo('{S} .c2',{{autoAlpha:0,y:20}},{{autoAlpha:1,y:0,duration:.4,ease:{E}}},{g + .2:.2f});",
                f"tl.to('{S} .icw.r,{S} .pill.bad',{{autoAlpha:0,scale:.6,duration:.3}},{g + .3:.2f});",
                f"tl.fromTo('{S} .icw.g',{{autoAlpha:0,scale:.4}},{{autoAlpha:1,scale:1,duration:.5,ease:'back.out(2.2)'}},{g + .4:.2f});",
                f"tl.fromTo('{S} .pill.good',{{autoAlpha:0,scale:.6}},{{autoAlpha:1,scale:1,duration:.5,ease:'back.out(2.2)'}},{g + .45:.2f});",
                f"tl.to('{S} .step',{{borderColor:'#1B8A3A',boxShadow:'0 0 0 18px rgba(27,138,58,.14), 0 30px 70px -24px rgba(29,29,31,.22)',duration:.5}},{g + .4:.2f});",
                f"tl.to('{S} .step',{{boxShadow:'0 0 0 0px rgba(27,138,58,0), 0 30px 70px -24px rgba(29,29,31,.22)',duration:.8}},{g + 1.0:.2f});",
                f"tl.from('{S} #provenplate',{{autoAlpha:0,y:50,duration:.7,ease:{E}}},{g + 1.2:.2f});",
            ]
        elif i == 4:
            js += [
                f"tl.from('{S} .tlc',{{autoAlpha:0,y:50,duration:.6,ease:{E}}},{v:.2f});",
                f"tl.from('{S} .rail',{{scaleX:0,transformOrigin:'0 50%',duration:.9,ease:'power2.out'}},{v + .3:.2f});",
                f"tl.from('{S} .nd:not(.guide)',{{autoAlpha:0,y:24,duration:.4,stagger:.16,ease:'back.out(1.8)'}},{v + .4:.2f});",
                f"tl.from('{S} .fb',{{autoAlpha:0,y:10,duration:.4,ease:'back.out(2)'}},{v + 1.3:.2f});",
                f"tl.from('{S} .gapline',{{scaleX:0,transformOrigin:'0 50%',duration:.7,ease:'power2.inOut'}},{v + 1.5:.2f});",
                f"tl.from('{S} .nd.guide',{{autoAlpha:0,scale:.6,duration:.5,ease:'back.out(2)'}},{v + 2.1:.2f});",
                f"tl.from('{S} .brace',{{scaleX:0,autoAlpha:0,duration:.6,ease:'power2.out'}},{v + 2.4:.2f});",
            ]
        elif i == 5:
            vw = f["vw"]
            cw = int(vw * .64)
            pos = [(0, 0, -7), (vw * .12, 40, -2.5), (vw * .24, 90, 2.5), (vw * .36, 150, 7)]
            for n, (x, y, r) in enumerate(pos):
                js.append(f"tl.set('{S} .p{n}',{{x:{x:.0f},y:{y},rotation:{r}}},0);")
            js += [
                f"tl.from('{S} .pr',{{autoAlpha:0,y:'+=120',rotation:0,x:{vw * .18:.0f},duration:.7,stagger:.18,ease:{E}}},{v:.2f});",
                f"tl.from('{S} .cnt',{{autoAlpha:0,scale:.7,duration:.6,ease:'back.out(1.8)'}},{v + 1.2:.2f});",
            ]
        t += dur

    chrome = (f'<div id="chrome" class="chrome clip" data-start="0" data-duration="{total}" data-track-index="1">'
              f'<div class="brand"><img src="assets/logo.svg" alt="">FirstRun</div><div class="kick">docs that work</div></div>')
    js.insert(0, f"tl.fromTo('#prog',{{scaleX:0}},{{scaleX:1,duration:{total},ease:'none'}},0);")
    js.insert(1, f"tl.fromTo('#bgfx .glow',{{x:0,y:0}},{{x:{-f['w'] * .25:.0f},y:{f['h'] * .2:.0f},duration:{total},ease:'sine.inOut'}},0);")
    doc = f"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><title>FirstRun teaser</title>
<script src="assets/gsap.min.js"></script>
<style>{css(f)}</style></head><body>
<div id="root" data-composition-id="firstrun-teaser" data-start="0" data-duration="{total}" data-width="{f['w']}" data-height="{f['h']}">
<div id="bgfx" class="clip" data-start="0" data-duration="{total}" data-track-index="0"><div class="glow"></div></div>
{chrome}
{chr(10).join(html)}
<div id="prog" class="prog clip" data-start="0" data-duration="{total}" data-track-index="{len(sc) + 2}"></div>
</div>
<script>
const tl=gsap.timeline({{paused:true}});
{chr(10).join(js)}
window.__timelines=window.__timelines||{{}};window.__timelines['firstrun-teaser']=tl;
</script></body></html>
"""
    (HERE / "index.html").write_text(doc, encoding="utf-8")
    (HERE / "meta.json").write_text(json.dumps({"id": "firstrun-teaser", "name": "firstrun-teaser", "width": f["w"], "height": f["h"], "fps": 30}, indent=2), encoding="utf-8")
    print(f"{fmt}: {len(sc)} scenes, {total}s, {f['w']}x{f['h']}")


if __name__ == "__main__":
    build(sys.argv[1] if len(sys.argv) > 1 else "4x5")

toolu_01YRtvAiigfDMedhpRbSGh4w.content:
"""Build the FirstRun teaser composition for one format.

Usage: python build_teaser.py 4x5|9x16|16x9

Writes index.html and meta.json in this folder. Every fact on screen is listed
with its source in VERIFY.md. Look follows firstrun-concept/DESIGN.md with the
site palette: light page, Geist, accent #0A66D6, pass #1B8A3A, fail #C4281C.
"""
import json
import sys
from pathlib import Path

HERE = Path(__file__).parent

FMT = {
    "4x5": dict(w=1080, h=1350, land=False, pad="176px 72px 96px", hl=74, cap=38, lab=24, vw=936, gap=34, mono=36),
    "9x16": dict(w=1080, h=1920, land=False, pad="250px 72px 300px", hl=84, cap=42, lab=26, vw=936, gap=48, mono=36),
    "16x9": dict(w=1920, h=1080, land=True, pad="150px 110px 90px", hl=70, cap=34, lab=22, vw=980, gap=26, mono=36),
}

# Scene durations in seconds. The hook is short so scene 2 builds inside the first 5 s.
DUR = [4.5, 5.5, 5.5, 6.5, 6.0, 4.5, 4.0]
XF = 0.4

CHECK = '<svg class="ic" viewBox="0 0 34 34"><circle cx="17" cy="17" r="17"/><path d="M10 17.5l4.6 4.6L24 12.5"/></svg>'
CROSS = '<svg class="ic bad" viewBox="0 0 34 34"><circle cx="17" cy="17" r="17"/><path d="M11.5 11.5l11 11M22.5 11.5l-11 11"/></svg>'


def step_card(cid: str, green_layer: bool) -> str:
    """The step 10 card. With green_layer it also holds the passed state, hidden at start."""
    g = ""
    if green_layer:
        g = (
            f'<span class="icw g">{CHECK}</span>'
        )
    return f"""
<div class="card step" id="{cid}">
  <div class="sh">
    <span class="icwrap"><span class="icw r">{CROSS}</span>{g}</span>
    <div class="stt"><div class="k mono">Step 10 of 10</div><div class="t">Generate 6 years of Jaffle Shop data</div></div>
    <span class="pillwrap"><span class="pill bad">failed, exit 2</span>{'<span class="pill good">passed, exit 0</span>' if green_layer else ''}</span>
  </div>
  <div class="cmdl mono"><b>$</b> <span class="cw"><span class="c1">jafgen --years 6</span>{'<span class="c2">jafgen 6</span>' if green_layer else ''}</span></div>
  <div class="errl mono"><span>No such option: --years</span></div>
  <div class="scan"></div>
</div>"""


def scenes() -> list[dict]:
    return [
        dict(label="dbt DuckDB guide", hl='Step 10 of the dbt guide <span class="r">fails</span>.',
             vis=step_card("stepA", False),
             cap="Copy the command from the docs, and jafgen rejects the flag."),
        dict(label="1 · Diagnose", hl="FirstRun reads the real error.",
             vis='<div class="card plate" id="errplate"><div class="bar mono">Attempt 1 output, from the run</div>'
                 '<div class="pimg"><img src="assets/plates/error.png" alt=""><i class="uline"></i></div></div>'
                 '<div class="chip" id="chip1"><span class="dot r"></span>Classified as a docs bug, confidence 1.0</div>',
             cap="The usage line shows <span class=\"m\">years</span> is now a positional argument."),
        dict(label="2 · Fix", hl="The patch drops one flag.",
             vis='<div class="card diff"><div class="bar mono">patch.diff · the jafgen line in the guide</div>'
                 '<div class="ctx mono">to generate data for 6 years, run</div>'
                 '<div class="dl del mono"><i>-</i><span class="st">jafgen --years 6<u></u></span></div>'
                 '<div class="dl add mono"><i>+</i><span>jafgen 6</span></div></div>',
             cap="FirstRun edits the docs sentence, then drafts the PR body."),
        dict(label="3 · Prove", hl='A fresh container passes <span class="g">9 of 9</span>.',
             vis=step_card("stepB", True) +
                 '<div class="card plate sm" id="provenplate"><div class="pimg"><img src="assets/plates/proven.png" alt=""></div></div>',
             cap="The proof run makes no model calls. The whole run cost $0.03."),
        dict(label="4 · Bisect", hl='jafgen <span class="r">0.4.6</span> removed the flag.',
             vis=timeline(),
             cap="5 probes, one clean container each, $0 in model calls. The guide shipped 11 months later."),
        dict(label="5 · Ship", hl="FirstRun opened 4 upstream docs PRs.",
             vis=pr_fan(),
             cap="dbt-labs #10149 and #10150, entireio/cli #2724, accuknox/help #671."),
        dict(end=True),
    ]


def timeline() -> str:
    rel = [("0.2.1", "Jan 2023", True), ("0.3.1", "Jan 2023", True), ("0.4.6", "Apr 2024", False),
           ("0.4.10", "Apr 2024", False), ("0.4.14", "Apr 2024", False)]
    nodes = "".join(
        f'<div class="nd {"ok" if ok else "no"}{" first" if v == "0.4.6" else ""}" style="left:{i * 15.5}%">'
        f'<div class="v mono">{v}</div><div class="dotn">{CHECK if ok else CROSS}</div><div class="d">{d}</div></div>'
        for i, (v, d, ok) in enumerate(rel)
    )
    return f"""
<div class="card tlc">
  <div class="bar mono">firstrun bisect --package jafgen</div>
  <div class="track">
    <div class="rail"></div><div class="gapline"></div>
    {nodes}
    <div class="nd guide" style="left:92%"><div class="v mono">guide</div><div class="dotn"><span></span></div><div class="d">Mar 2025</div></div>
    <div class="brace"><span>11 months</span></div>
    <div class="fb mono">first bad</div>
  </div>
</div>"""


def pr_fan() -> str:
    prs = ["pr-10149", "pr-10150", "pr-2724", "pr-671"]
    cards = "".join(f'<img class="pr p{i}" src="assets/plates/{p}.webp" alt="">' for i, p in enumerate(prs))
    return f'<div class="fan">{cards}<div class="cnt"><b>4</b><span>upstream docs PRs</span></div></div>'


def css(f: dict) -> str:
    w, h, vw = f["w"], f["h"], f["vw"]
    if f["land"]:
        grid = (f"grid-template-columns:700px {vw}px;column-gap:{w - 220 - 700 - vw}px;"
                "grid-template-areas:'label vis' 'hl vis' 'cap vis';grid-template-rows:auto auto 1fr;align-content:center;")
        txt_align = "align-self:start"
    else:
        grid = (f"grid-template-columns:{vw}px;grid-template-areas:'label' 'hl' 'vis' 'cap';"
                "grid-template-rows:auto auto auto auto;align-content:center;")
        txt_align = ""
    return f"""
@font-face{{font-family:'Geist';src:url('assets/fonts/Geist.woff2') format('woff2');font-weight:100 900}}
@font-face{{font-family:'Geist Mono';src:url('assets/fonts/GeistMono.woff2') format('woff2');font-weight:100 900}}
:root{{--bg:#F4F5F9;--card:#FFFFFF;--ink:#1D1D1F;--muted:#5E5E66;--line:#D8D8DE;--soft:#ECEDF2;--pass:#1B8A3A;--fail:#C4281C;--accent:#0A66D6;
--pass-soft:#E6F4EA;--fail-soft:#FCEBEA;--accent-soft:#E7F0FC;--shadow:0 1px 2px rgba(29,29,31,.05),0 30px 70px -24px rgba(29,29,31,.22)}}
*{{box-sizing:border-box;margin:0;padding:0}}
html,body{{width:{w}px;height:{h}px;overflow:hidden;background:var(--bg)}}
#root{{position:relative;width:{w}px;height:{h}px;overflow:hidden;background:var(--bg);color:var(--ink);font-family:'Geist',sans-serif;-webkit-font-smoothing:antialiased}}
#bgfx{{position:absolute;inset:0}}
#bgfx .glow{{position:absolute;width:{max(w, h)}px;height:{max(w, h)}px;left:{w * .2}px;top:{-h * .35}px;border-radius:50%;background:radial-gradient(circle,#FFFFFF 0%,rgba(255,255,255,0) 62%)}}
.mono{{font-family:'Geist Mono',monospace}}
.chrome{{position:absolute;left:{72 if not f['land'] else 110}px;right:{72 if not f['land'] else 110}px;top:{56 if not f['land'] else 48}px;display:flex;justify-content:space-between;align-items:center;z-index:20}}
.chrome .brand{{display:flex;align-items:center;gap:16px;font-weight:700;font-size:34px;letter-spacing:-.02em}}
.chrome .brand img{{width:52px;height:52px}}
.chrome .kick{{font:500 24px 'Geist Mono';color:var(--muted);letter-spacing:.02em}}
.prog{{position:absolute;left:0;bottom:0;height:8px;width:100%;background:var(--accent);transform-origin:0 50%;z-index:20}}
.scene{{position:absolute;inset:0;z-index:5}}
.sc{{position:absolute;inset:0;padding:{f['pad']};display:grid;{grid}row-gap:{f['gap']}px}}
.label{{grid-area:label;font:600 {f['lab']}px 'Geist Mono';letter-spacing:.12em;text-transform:uppercase;color:var(--accent);{txt_align}}}
.hl{{grid-area:hl;font-weight:700;font-size:{f['hl']}px;line-height:1.04;letter-spacing:-.04em}}
.hl .r{{color:var(--fail)}} .hl .g{{color:var(--pass)}}
.cap{{grid-area:cap;font-weight:500;font-size:{f['cap']}px;line-height:1.28;letter-spacing:-.015em;color:var(--ink);{'align-self:start;margin-top:10px' if f['land'] else ''}}}
.cap .m{{font-family:'Geist Mono';font-size:.92em;background:var(--accent-soft);color:var(--accent);padding:0 .2em;border-radius:6px}}
.vis{{grid-area:vis;position:relative;display:flex;flex-direction:column;gap:24px;align-self:center}}
.card{{background:var(--card);border:1px solid rgba(29,29,31,.08);border-radius:26px;box-shadow:var(--shadow);overflow:hidden;position:relative}}
.bar{{padding:20px 28px;border-bottom:1px solid var(--soft);font-size:24px;color:var(--muted)}}
.ic{{width:100%;height:100%;display:block}} .ic circle{{fill:var(--pass)}} .ic.bad circle{{fill:var(--fail)}}
.ic path{{stroke:#fff;stroke-width:3;fill:none;stroke-linecap:round;stroke-linejoin:round}}
/* step card */
.step{{border:3px solid var(--fail)}}
.step .sh{{display:flex;align-items:center;gap:22px;padding:28px 30px 22px;border-bottom:1px solid var(--soft)}}
.icwrap{{position:relative;width:58px;height:58px;flex:none}} .icw{{position:absolute;inset:0}}
.stt{{flex:1;min-width:0}} .stt .k{{font-size:22px;color:var(--muted);margin-bottom:4px}} .stt .t{{font-size:30px;font-weight:600;letter-spacing:-.02em;line-height:1.15}}
.pillwrap{{position:relative;flex:none;display:grid}} .pillwrap .pill{{grid-area:1/1}}
.pill{{font:600 24px 'Geist';padding:10px 18px;border-radius:999px;white-space:nowrap;text-align:center}}
.pill.bad{{background:var(--fail-soft);color:var(--fail)}} .pill.good{{background:var(--pass-soft);color:var(--pass)}}
.cmdl{{padding:26px 30px 8px;font-size:{f['mono'] + 6}px;font-weight:500}} .cmdl b{{color:var(--muted);font-weight:400}}
.cw{{position:relative;display:inline-grid}} .cw>span{{grid-area:1/1;white-space:nowrap}}
.errl{{margin:14px 30px 30px;padding:16px 22px;border-radius:14px;background:var(--fail-soft);color:var(--fail);font-size:{f['mono'] - 4}px;font-weight:500;overflow:hidden}}
.scan{{position:absolute;left:0;right:0;top:0;height:90px;background:linear-gradient(180deg,rgba(10,102,214,0) 0%,rgba(10,102,214,.16) 50%,rgba(10,102,214,0) 100%);pointer-events:none}}
/* plates */
.plate .pimg{{position:relative;padding:22px 26px}} .plate img{{display:block;width:100%;border-radius:10px}}
.plate.sm .pimg{{padding:18px 22px}}
.uline{{position:absolute;left:calc(26px + 60.2% * ({vw - 52}/{vw}));width:calc(20.6% * ({vw - 52}/{vw}));top:calc(22px + 84% * 1);height:6px;border-radius:3px;background:var(--fail);transform-origin:0 50%}}
.chip{{align-self:flex-start;display:flex;align-items:center;gap:14px;padding:14px 24px;border-radius:999px;background:var(--card);border:1px solid rgba(29,29,31,.08);box-shadow:0 1px 2px rgba(29,29,31,.06);font-size:28px;font-weight:600}}
.dot{{width:16px;height:16px;border-radius:50%}} .dot.r{{background:var(--fail)}}
/* diff */
.diff .ctx{{padding:26px 30px 6px;font-size:28px;color:var(--muted)}}
.dl{{display:flex;align-items:center;gap:22px;margin:12px 22px;padding:20px 22px;border-radius:14px;font-size:{f['mono'] + 6}px;font-weight:500}}
.dl i{{font-style:normal;width:30px;text-align:center;font-weight:700}}
.dl.del{{background:var(--fail-soft);color:var(--fail)}} .dl.add{{background:var(--pass-soft);color:var(--pass);margin-bottom:30px}}
.dl .st{{position:relative}} .dl .st u{{position:absolute;left:-4px;right:-4px;top:52%;height:4px;background:var(--fail);border-radius:2px;transform-origin:0 50%}}
/* timeline */
.track{{position:relative;height:300px;margin:0 34px}}
.rail{{position:absolute;left:4%;right:30%;top:132px;height:4px;background:var(--line);border-radius:2px}}
.gapline{{position:absolute;left:66%;right:4%;top:132px;height:0;border-top:4px dashed var(--line)}}
.nd{{position:absolute;top:48px;width:110px;margin-left:-14px;display:flex;flex-direction:column;align-items:center}}
.nd .v{{font-size:28px;font-weight:600;height:40px}}
.nd .dotn{{width:56px;height:56px;margin-top:10px;border-radius:50%;background:var(--card)}}
.nd .d{{margin-top:14px;font-size:22px;color:var(--muted);white-space:nowrap}}
.nd.no .v{{color:var(--fail)}} .nd.ok .v{{color:var(--pass)}}
.nd.guide .v{{color:var(--accent)}} .nd.guide .dotn{{display:grid;place-items:center;border:4px solid var(--accent)}} .nd.guide .dotn span{{width:22px;height:22px;border-radius:50%;background:var(--accent)}}
.nd.first .dotn{{box-shadow:0 0 0 8px rgba(196,40,28,.16)}}
.brace{{position:absolute;left:31%;width:62%;top:226px;height:22px;border:3px solid var(--accent);border-top:none;border-radius:0 0 14px 14px;transform-origin:0 0}}
.brace span{{position:absolute;left:50%;top:30px;transform:translateX(-50%);font-weight:700;font-size:32px;color:var(--accent);white-space:nowrap;letter-spacing:-.02em}}
.fb{{position:absolute;left:31%;top:8px;margin-left:-14px;font-size:20px;color:#fff;background:var(--fail);padding:4px 12px;border-radius:999px;transform:translateX(0)}}
.tlc .track{{margin-bottom:24px}}
/* PR fan */
.fan{{position:relative;height:{560 if not f['land'] else 620}px}}
.pr{{position:absolute;width:{int(vw * .64)}px;border-radius:16px;box-shadow:var(--shadow);border:1px solid rgba(29,29,31,.1);background:#fff}}
.cnt{{position:absolute;right:0;bottom:0;display:flex;align-items:baseline;gap:16px;background:var(--card);padding:18px 30px;border-radius:22px;box-shadow:var(--shadow)}}
.cnt b{{font-size:110px;line-height:1;color:var(--accent);letter-spacing:-.04em}} .cnt span{{font-size:32px;font-weight:600;max-width:200px;line-height:1.1}}
/* end card */
.endc{{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:30px;padding-bottom:40px}}
.endc .logo{{width:170px;height:170px}}
.endc .wm{{font-weight:700;font-size:{120 if f['land'] else 116}px;letter-spacing:-.05em;line-height:1}}
.endc .tag{{font-weight:500;font-size:48px;color:var(--muted);letter-spacing:-.02em}}
.endc .tag b{{color:var(--fail);font-weight:600}} .endc .tag i{{color:var(--accent);font-style:normal;font-weight:600}} .endc .tag em{{color:var(--pass);font-style:normal;font-weight:600}}
.endc .url{{margin-top:14px;font:600 44px 'Geist Mono';color:#fff;background:var(--accent);padding:20px 38px;border-radius:999px;letter-spacing:-.01em}}
.endc .built{{margin-top:26px;display:flex;align-items:center;gap:18px;font-size:26px;color:var(--muted);font-weight:500}}
.endc .built img{{width:52px;height:52px;border-radius:12px}}
"""


def build(fmt: str) -> None:
    f = FMT[fmt]
    sc = scenes()
    total = round(sum(DUR), 2)
    html, js, t = [], [], 0.0
    E = "'expo.out'"
    for i, s in enumerate(sc):
        dur = DUR[i]
        start = max(0.0, t - (XF if i else 0))
        length = dur + (XF if i else 0)
        sid = f"s{i}"
        if s.get("end"):
            inner = ('<div class="endc"><img class="logo" src="assets/logo.svg" alt=""><div class="wm">FirstRun</div>'
                     '<div class="tag"><b>Break.</b> <i>Fix.</i> <em>Prove.</em></div>'
                     '<div class="url">firstrun.atharvashah.com</div>'
                     '<div class="built">Built with <img src="assets/logos/entire-apple.png" alt="Entire">'
                     '<img src="assets/logos/neatlogs-apple.png" alt="neatlogs"><img src="assets/logos/cfoai-apple.png" alt="cfo.ai"></div></div>')
        else:
            inner = (f'<div class="sc"><div class="label">{s["label"]}</div><div class="hl">{s["hl"]}</div>'
                     f'<div class="vis">{s["vis"]}</div><div class="cap">{s["cap"]}</div></div>')
        html.append(f'<div id="{sid}" class="scene clip" data-start="{start:.2f}" data-duration="{length:.2f}" data-track-index="{i + 2}">{inner}</div>')
        S = f"#{sid}"
        if i:
            js.append(f"tl.fromTo('{S}',{{autoAlpha:0,y:24,filter:'blur(8px)'}},{{autoAlpha:1,y:0,filter:'blur(0px)',duration:{XF},ease:'power2.out'}},{start:.2f});")
            js.append(f"tl.to('#s{i - 1}',{{autoAlpha:0,duration:.25,ease:'power1.in'}},{start:.2f});")
        b = start + 0.2 if i else 0.0
        if i == 0:
            # Frame 0 is the thumbnail: drawn complete. It moves from frame 0.
            js += [
                f"tl.fromTo('{S} .vis',{{scale:1,y:0,rotation:-1.2}},{{scale:1.06,y:-14,rotation:1.2,duration:{dur},ease:'sine.inOut'}},0);",
                f"tl.fromTo('{S} .scan',{{y:-100}},{{y:420,duration:1.3,ease:'power1.inOut',repeat:2}},0);",
                f"tl.fromTo('{S} .step',{{boxShadow:'0 0 0 0px rgba(196,40,28,.0), 0 30px 70px -24px rgba(29,29,31,.22)'}},{{boxShadow:'0 0 0 22px rgba(196,40,28,.18), 0 30px 70px -24px rgba(29,29,31,.22)',duration:.7,ease:'sine.inOut',yoyo:true,repeat:5}},0);",
                f"tl.fromTo('{S} .errl',{{x:0}},{{keyframes:{{x:[-10,10,-8,8,-4,0]}},duration:.5,ease:'none'}},1.0);",
                f"tl.from('{S} .cap',{{autoAlpha:0,y:30,duration:.55,ease:{E}}},1.0);",
            ]
            t += dur
            continue
        if s.get("end"):
            js += [
                f"tl.from('{S} .logo',{{autoAlpha:0,scale:.6,rotation:-12,duration:.8,ease:'back.out(1.6)'}},{b:.2f});",
                f"tl.from('{S} .wm',{{autoAlpha:0,y:40,duration:.7,ease:{E}}},{b + .25:.2f});",
                f"tl.from('{S} .tag>*',{{autoAlpha:0,y:24,duration:.5,stagger:.22,ease:{E}}},{b + .5:.2f});",
                f"tl.from('{S} .url',{{autoAlpha:0,scale:.85,duration:.6,ease:'back.out(1.8)'}},{b + 1.2:.2f});",
                f"tl.from('{S} .built',{{autoAlpha:0,y:20,duration:.5,ease:{E}}},{b + 1.6:.2f});",
                f"tl.to('{S} .endc',{{scale:1.04,duration:{dur:.2f},ease:'none'}},{b:.2f});",
            ]
            t += dur
            continue
        js += [
            f"tl.from('{S} .label',{{autoAlpha:0,x:-30,duration:.45,ease:{E}}},{b:.2f});",
            f"tl.from('{S} .hl',{{autoAlpha:0,y:40,duration:.7,ease:{E}}},{b + .1:.2f});",
            f"tl.from('{S} .cap',{{autoAlpha:0,y:24,duration:.55,ease:{E}}},{b + 1.3:.2f});",
            f"tl.to('{S} .vis',{{scale:1.025,duration:{dur:.2f},ease:'none'}},{b:.2f});",
        ]
        v = b + 0.35
        if i == 1:
            js += [
                f"tl.from('{S} #errplate',{{autoAlpha:0,y:50,scale:.96,duration:.7,ease:{E}}},{v:.2f});",
                f"tl.from('{S} .uline',{{scaleX:0,duration:.45,ease:'power2.inOut'}},{v + .9:.2f});",
                f"tl.from('{S} #chip1',{{autoAlpha:0,y:20,duration:.5,ease:'back.out(1.6)'}},{v + 1.3:.2f});",
            ]
        elif i == 2:
            js += [
                f"tl.from('{S} .diff',{{autoAlpha:0,y:50,duration:.6,ease:{E}}},{v:.2f});",
                f"tl.from('{S} .dl.del',{{autoAlpha:0,x:-60,duration:.5,ease:{E}}},{v + .35:.2f});",
                f"tl.from('{S} .dl.del .st u',{{scaleX:0,duration:.45,ease:'power2.inOut'}},{v + 1.1:.2f});",
                f"tl.to('{S} .dl.del',{{opacity:.55,duration:.4}},{v + 1.5:.2f});",
                f"tl.from('{S} .dl.add',{{autoAlpha:0,x:60,duration:.6,ease:'back.out(1.4)'}},{v + 1.6:.2f});",
            ]
        elif i == 3:
            # The red step turns green: the hero moment.
            g = v + 0.9
            js += [
                f"tl.from('{S} .step',{{autoAlpha:0,y:40,duration:.5,ease:{E}}},{v:.2f});",
                f"tl.set('{S} .icw.g,{S} .pill.good,{S} .c2',{{autoAlpha:0}},0);",
                f"tl.fromTo('{S} .scan',{{y:-100}},{{y:420,duration:.8,ease:'power1.inOut'}},{v + .1:.2f});",
                f"tl.to('{S} .errl',{{height:0,paddingTop:0,paddingBottom:0,marginTop:0,marginBottom:22,opacity:0,duration:.5,ease:'power2.inOut'}},{g:.2f});",
                f"tl.to('{S} .c1',{{autoAlpha:0,y:-20,duration:.3}},{g:.2f});",
                f"tl.fromTo('{S} .c2',{{autoAlpha:0,y:20}},{{autoAlpha:1,y:0,duration:.4,ease:{E}}},{g + .2:.2f});",
                f"tl.to('{S} .icw.r,{S} .pill.bad',{{autoAlpha:0,scale:.6,duration:.3}},{g + .3:.2f});",
                f"tl.fromTo('{S} .icw.g',{{autoAlpha:0,scale:.4}},{{autoAlpha:1,scale:1,duration:.5,ease:'back.out(2.2)'}},{g + .4:.2f});",
                f"tl.fromTo('{S} .pill.good',{{autoAlpha:0,scale:.6}},{{autoAlpha:1,scale:1,duration:.5,ease:'back.out(2.2)'}},{g + .45:.2f});",
                f"tl.to('{S} .step',{{borderColor:'#1B8A3A',boxShadow:'0 0 0 18px rgba(27,138,58,.14), 0 30px 70px -24px rgba(29,29,31,.22)',duration:.5}},{g + .4:.2f});",
                f"tl.to('{S} .step',{{boxShadow:'0 0 0 0px rgba(27,138,58,0), 0 30px 70px -24px rgba(29,29,31,.22)',duration:.8}},{g + 1.0:.2f});",
                f"tl.from('{S} #provenplate',{{autoAlpha:0,y:50,duration:.7,ease:{E}}},{g + 1.2:.2f});",
            ]
        elif i == 4:
            js += [
                f"tl.from('{S} .tlc',{{autoAlpha:0,y:50,duration:.6,ease:{E}}},{v:.2f});",
                f"tl.from('{S} .rail',{{scaleX:0,transformOrigin:'0 50%',duration:.9,ease:'power2.out'}},{v + .3:.2f});",
                f"tl.from('{S} .nd:not(.guide)',{{autoAlpha:0,y:24,duration:.4,stagger:.16,ease:'back.out(1.8)'}},{v + .4:.2f});",
                f"tl.from('{S} .fb',{{autoAlpha:0,y:10,duration:.4,ease:'back.out(2)'}},{v + 1.3:.2f});",
                f"tl.from('{S} .gapline',{{scaleX:0,transformOrigin:'0 50%',duration:.7,ease:'power2.inOut'}},{v + 1.5:.2f});",
                f"tl.from('{S} .nd.guide',{{autoAlpha:0,scale:.6,duration:.5,ease:'back.out(2)'}},{v + 2.1:.2f});",
                f"tl.from('{S} .brace',{{scaleX:0,autoAlpha:0,duration:.6,ease:'power2.out'}},{v + 2.4:.2f});",
            ]
        elif i == 5:
            vw = f["vw"]
            cw = int(vw * .64)
            pos = [(0, 0, -7), (vw * .12, 40, -2.5), (vw * .24, 90, 2.5), (vw * .36, 150, 7)]
            for n, (x, y, r) in enumerate(pos):
                js.append(f"tl.set('{S} .p{n}',{{x:{x:.0f},y:{y},rotation:{r}}},0);")
            js += [
                f"tl.from('{S} .pr',{{autoAlpha:0,y:'+=120',rotation:0,x:{vw * .18:.0f},duration:.7,stagger:.18,ease:{E}}},{v:.2f});",
                f"tl.from('{S} .cnt',{{autoAlpha:0,scale:.7,duration:.6,ease:'back.out(1.8)'}},{v + 1.2:.2f});",
            ]
        t += dur

    chrome = (f'<div id="chrome" class="chrome clip" data-start="0" data-duration="{total}" data-track-index="1">'
              f'<div class="brand"><img src="assets/logo.svg" alt="">FirstRun</div><div class="kick">docs that work</div></div>')
    js.insert(0, f"tl.fromTo('#prog',{{scaleX:0}},{{scaleX:1,duration:{total},ease:'none'}},0);")
    js.insert(1, f"tl.fromTo('#bgfx .glow',{{x:0,y:0}},{{x:{-f['w'] * .25:.0f},y:{f['h'] * .2:.0f},duration:{total},ease:'sine.inOut'}},0);")
    doc = f"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><title>FirstRun teaser</title>
<script src="assets/gsap.min.js"></script>
<style>{css(f)}</style></head><body>
<div id="root" data-composition-id="firstrun-teaser" data-start="0" data-duration="{total}" data-width="{f['w']}" data-height="{f['h']}">
<div id="bgfx" class="clip" data-start="0" data-duration="{total}" data-track-index="0"><div class="glow"></div></div>
{chrome}
{chr(10).join(html)}
<div id="prog" class="prog clip" data-start="0" data-duration="{total}" data-track-index="{len(sc) + 2}"></div>
</div>
<script>
const tl=gsap.timeline({{paused:true}});
{chr(10).join(js)}
window.__timelines=window.__timelines||{{}};window.__timelines['firstrun-teaser']=tl;
</script></body></html>
"""
    (HERE / "index.html").write_text(doc, encoding="utf-8")
    (HERE / "meta.json").write_text(json.dumps({"id": "firstrun-teaser", "name": "firstrun-teaser", "width": f["w"], "height": f["h"], "fps": 30}, indent=2), encoding="utf-8")
    print(f"{fmt}: {len(sc)} scenes, {total}s, {f['w']}x{f['h']}")


if __name__ == "__main__":
    build(sys.argv[1] if len(sys.argv) > 1 else "4x5")

